import { StageInscription } from '../../../../core/models/stage-inscription.model';

export const ATTESTATION_BG_IMAGE =
  'data:image/png;base64,';

export function generateAttestationHtml(item: StageInscription): string {
  const trainee =
    `${item.studentFirstName || ''} ${item.studentLastName || ''}`.trim() || 'Stagiaire';
  const cin = item.studentCin || '—';

  const formatShortDate = (val?: any): string => {
    if (!val) return '';
    try {
      const d = new Date(val);
      if (isNaN(d.getTime())) return String(val);
      return d.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });
    } catch {
      return String(val);
    }
  };

  const formatLongDate = (val?: any): string => {
    try {
      const d = val ? new Date(val) : new Date();
      if (isNaN(d.getTime())) return String(val);
      return d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' });
    } catch {
      return String(val);
    }
  };

  const startDate = formatShortDate(item.createdAt) || '01/07/2026';
  let endDate = formatShortDate(item.completedAt);
  if (!endDate) {
    if (item.createdAt) {
      const d = new Date(item.createdAt);
      const weeks = item.stageDurationWeeks || 12;
      d.setDate(d.getDate() + weeks * 7);
      endDate = formatShortDate(d);
    } else {
      endDate = '31/07/2026';
    }
  }

  const issueDate = formatLongDate(item.completedAt || new Date());
  const company = 'BEE CODERS';
  const companyCapitalized = 'Bee Coders';
  const tagline = 'Développement Logiciel & Solutions Digitales';
  const title = 'ATTESTATION DE STAGE';
  const director = 'Monsieur Neffati Ahmed';
  const role = 'Directeur Général';
  const city = 'Fait à Tunis,';
  const signature = 'Signature et cachet';
  const note = 'Nb: La présente attestation est délivrée en un seul original.';
  const location = 'Lac1-Tunis';
  const phone = '+216 58 84 00 64';
  const email = 'admin@beecoders.tn';

  return `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Attestation de Stage - ${trainee}</title>
<style>
@page { size: A4 portrait; margin: 0; }
* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  background: #334155;
  font-family: Arial, Helvetica, sans-serif;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
body { min-height: 100vh; }

.no-print {
  position: fixed;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  background: #0f172a;
  color: #fff;
  padding: 10px 24px;
  border-radius: 9999px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.35);
  display: flex;
  align-items: center;
  gap: 16px;
  z-index: 1000;
  font-family: Arial, sans-serif;
  font-size: 13px;
}
.no-print button {
  background: #C62761;
  color: white;
  border: none;
  padding: 7px 20px;
  border-radius: 9999px;
  font-weight: 700;
  cursor: pointer;
  font-size: 12px;
  transition: all 0.2s;
}
.no-print button:hover {
  background: #a81c4e;
  transform: scale(1.03);
}

.page-wrap {
  padding: 70px 24px 40px;
  display: flex;
  justify-content: center;
}
.page {
  position: relative;
  width: 210mm;
  height: 297mm;
  background: #fff;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(0,0,0,0.25);
  container-type: inline-size;
}
.background {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
}
.mask {
  position: absolute;
  background: #fff;
  z-index: 1;
}
.text {
  position: absolute;
  z-index: 2;
  color: #171717;
  margin: 0;
  padding: 0;
}

.company {
  left: 13.20%;
  top: 7.72%;
  width: 31%;
  font-family: Arial, Helvetica, sans-serif;
  font-weight: 600;
  font-size: 24px;
  font-size: 3.03cqw;
  letter-spacing: .01em;
}
.tagline {
  left: 13.20%;
  top: 10.83%;
  width: 42%;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16px;
  font-size: 2.03cqw;
  color: #8a8a8a;
}
.title {
  left: 20.0%;
  top: 19.18%;
  width: 60%;
  text-align: center;
  font-family: "Times New Roman", Times, serif;
  font-weight: 700;
  font-size: 26px;
  font-size: 3.26cqw;
  text-decoration: underline;
}
.body {
  left: 13.18%;
  top: 27.65%;
  width: 73.8%;
  font-family: "Times New Roman", Times, serif;
  font-size: 16px;
  font-size: 2.03cqw;
  line-height: 1.57;
  color: #555;
  text-align: left;
}
.body p {
  margin: 0 0 16px;
  margin: 0 0 2cqw;
}
.body .strong {
  font-weight: 700;
  color: #111;
}
.identity-line { text-align: center; }
.date-line { text-align: center; margin-top: -.3% !important; }
.signature-date {
  left: 13.18%;
  top: 57.26%;
  width: 32%;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16.5px;
  font-size: 2.08cqw;
  color: #666;
}

/* white masks aligned to the text */
.m-company { left: 12.7%; top: 6.75%; width: 33.2%; height: 3.65%; }
.m-tagline { left: 12.7%; top: 10.40%; width: 45.5%; height: 2.1%; }
.m-title { left: 19.3%; top: 18.65%; width: 61.6%; height: 4.15%; }
.m-body { left: 12.45%; top: 26.85%; width: 75.6%; height: 26.5%; }
.m-date { left: 12.5%; top: 56.4%; width: 37%; height: 3.2%; }

@media print {
  html, body { background: #fff; margin: 0; padding: 0; }
  .no-print { display: none !important; }
  .page-wrap { padding: 0; margin: 0; }
  .page { width: 210mm; height: 297mm; box-shadow: none; margin: 0; }
}
</style>
</head>
<body>
<div class="no-print">
  <span>Modèle Officiel - Attestation de stage (${trainee})</span>
  <button type="button" onclick="window.print()">🖨️ Enregistrer en PDF / Imprimer</button>
</div>

<div class="page-wrap">
  <div class="page">
    <img class="background" src="${ATTESTATION_BG_IMAGE}" alt="Fond officiel attestation">

    <div class="mask m-company"></div><div class="mask m-tagline"></div><div class="mask m-title"></div>
    <div class="mask m-body"></div><div class="mask m-date"></div>

    <div class="text company">${company}</div>
    <div class="text tagline">${tagline}</div>
    <div class="text title">${title}</div>

    <div class="text body">
      <p>Je soussigné, <span class="strong">${director}</span>, agissant en qualité de <span class="strong">${role}</span> de la société <span class="strong">${companyCapitalized}</span>, atteste et certifie par la présente que :</p>
      <p class="identity-line"><span class="strong">${trainee}</span> titulaire de la carte d'identité nationale n° <span class="strong">${cin}</span> a effectué</p>
      <p class="identity-line date-line">un stage au sein de notre société <span class="strong">${startDate}</span> au <span class="strong">${endDate}</span>.</p>
      <p>Au cours de cette période, la stagiaire a fait preuve de sérieux, de rigueur et d'un réel engagement professionnel dans l'accomplissement des missions qui lui ont été confiées.</p>
      <p>La présente attestation est délivrée à l'intéressée sur sa demande, pour servir et valoir ce que de droit.</p>
    </div>
    <div class="text signature-date">le ${issueDate}</div>
  </div>
</div>

<script>
  window.onload = function() {
    setTimeout(function() { window.print(); }, 400);
  };
</script>
</body>
</html>`;
}
